insert into public.recipe_step (id, recipe_id, step_order, title, content, timer_seconds) values
  ('rec-tacos-de-pollo-step-1', 'rec-tacos-de-pollo', 1, 'Cocer el pollo', 'Pon la pechuga en una olla con agua y sal. Deja hervir a fuego medio.', 900),
  ('rec-tacos-de-pollo-step-2', 'rec-tacos-de-pollo', 2, 'Deshebrar', 'Saca el pollo, deja que se enfríe un poco y deshébralo con dos tenedores.', null),
  ('rec-tacos-de-pollo-step-3', 'rec-tacos-de-pollo', 3, 'Picar', 'Pica la cebolla y el cilantro finamente.', null),
  ('rec-tacos-de-pollo-step-4', 'rec-tacos-de-pollo', 4, 'Calentar tortillas', 'Calienta las tortillas en un comal con un poco de aceite y arma los tacos.', 120),
  ('rec-arroz-con-pollo-step-1', 'rec-arroz-con-pollo', 1, 'Dorar el arroz', 'Calienta el aceite y dora el arroz hasta que se vea transparente.', 300),
  ('rec-arroz-con-pollo-step-2', 'rec-arroz-con-pollo', 2, 'Licuar', 'Licúa el jitomate con la cebolla, el ajo y una taza de agua.', null),
  ('rec-arroz-con-pollo-step-3', 'rec-arroz-con-pollo', 3, 'Cocer', 'Agrega el licuado, el pollo en trozos y sal. Tapa y cocina a fuego bajo.', 1500),
  ('rec-arroz-con-pollo-step-4', 'rec-arroz-con-pollo', 4, 'Reposar', 'Apaga el fuego y deja reposar tapado antes de servir.', 300),
  ('rec-huevos-a-la-mexicana-step-1', 'rec-huevos-a-la-mexicana', 1, 'Picar', 'Pica el jitomate, la cebolla y el chile serrano.', null),
  ('rec-huevos-a-la-mexicana-step-2', 'rec-huevos-a-la-mexicana', 2, 'Sofreír', 'Sofríe la verdura en aceite caliente.', 180),
  ('rec-huevos-a-la-mexicana-step-3', 'rec-huevos-a-la-mexicana', 3, 'Agregar huevo', 'Agrega los huevos batidos con sal y mueve hasta que cuajen.', 240),
  ('rec-spaghetti-con-jitomate-step-1', 'rec-spaghetti-con-jitomate', 1, 'Cocer la pasta', 'Hierve agua con sal y cuece la pasta.', 600),
  ('rec-spaghetti-con-jitomate-step-2', 'rec-spaghetti-con-jitomate', 2, 'Salsa', 'Sofríe el ajo en aceite, agrega el jitomate picado y cocina hasta que espese.', 600),
  ('rec-spaghetti-con-jitomate-step-3', 'rec-spaghetti-con-jitomate', 3, 'Servir', 'Mezcla la pasta con la salsa y sirve con queso desmoronado.', null),
  ('rec-enfrijoladas-step-1', 'rec-enfrijoladas', 1, 'Licuar frijoles', 'Licúa los frijoles cocidos con un poco de su caldo y cebolla.', null),
  ('rec-enfrijoladas-step-2', 'rec-enfrijoladas', 2, 'Calentar salsa', 'Calienta el licuado en una olla con sal hasta que hierva.', 300),
  ('rec-enfrijoladas-step-3', 'rec-enfrijoladas', 3, 'Pasar tortillas', 'Pasa las tortillas por aceite caliente y luego por la salsa de frijol.', null),
  ('rec-enfrijoladas-step-4', 'rec-enfrijoladas', 4, 'Servir', 'Dobla las tortillas y sirve con crema y queso.', null),
  ('rec-avena-con-platano-step-1', 'rec-avena-con-platano', 1, 'Hervir', 'Calienta la leche con la avena a fuego medio moviendo seguido.', 420),
  ('rec-avena-con-platano-step-2', 'rec-avena-con-platano', 2, 'Servir', 'Sirve y agrega el plátano en rodajas.', null),
  ('rec-chilaquiles-rojos-step-1', 'rec-chilaquiles-rojos', 1, 'Freír la tortilla', 'Corta las tortillas en triángulos y fríelas en aceite hasta que estén doradas, unos 8 minutos.', 480),
  ('rec-chilaquiles-rojos-step-2', 'rec-chilaquiles-rojos', 2, 'Hacer la salsa', 'Licúa el jitomate con media cebolla, el ajo, los chiles y sal. Cocina la salsa 10 minutos.', 600),
  ('rec-chilaquiles-rojos-step-3', 'rec-chilaquiles-rojos', 3, 'Bañar los totopos', 'Agrega los totopos a la salsa y mezcla hasta cubrirlos.', null),
  ('rec-chilaquiles-rojos-step-4', 'rec-chilaquiles-rojos', 4, 'Servir', 'Sirve con crema, queso desmoronado y aros de cebolla.', null),
  ('rec-molletes-con-pico-de-gallo-step-1', 'rec-molletes-con-pico-de-gallo', 1, 'Cocer los frijoles', 'Cuece los frijoles en agua con sal hasta que estén suaves y macháquelos.', 3600),
  ('rec-molletes-con-pico-de-gallo-step-2', 'rec-molletes-con-pico-de-gallo', 2, 'Armar', 'Parte los bolillos, úntales frijol y cúbrelos con queso deshebrado.', null),
  ('rec-molletes-con-pico-de-gallo-step-3', 'rec-molletes-con-pico-de-gallo', 3, 'Gratinar', 'Hornea o calienta en comal tapado hasta que el queso se derrita, unos 8 minutos.', 480),
  ('rec-molletes-con-pico-de-gallo-step-4', 'rec-molletes-con-pico-de-gallo', 4, 'Pico de gallo', 'Pica jitomate, cebolla, cilantro y chile, mezcla con sal y sirve encima.', null),
  ('rec-huevos-rancheros-step-1', 'rec-huevos-rancheros', 1, 'Salsa ranchera', 'Licúa jitomate, un trozo de cebolla, ajo y chile. Cocina la salsa con sal 8 minutos.', 480),
  ('rec-huevos-rancheros-step-2', 'rec-huevos-rancheros', 2, 'Calentar tortillas', 'Pasa las tortillas por aceite caliente sin que se doren.', null),
  ('rec-huevos-rancheros-step-3', 'rec-huevos-rancheros', 3, 'Estrellar huevos', 'Fríe los huevos a tu gusto, unos 3 minutos.', 180),
  ('rec-huevos-rancheros-step-4', 'rec-huevos-rancheros', 4, 'Servir', 'Pon los huevos sobre las tortillas y báñalos con la salsa.', null),
  ('rec-pan-frances-step-1', 'rec-pan-frances', 1, 'Mezclar', 'Bate los huevos con la leche y la mitad del azúcar.', null),
  ('rec-pan-frances-step-2', 'rec-pan-frances', 2, 'Remojar', 'Pasa cada rebanada de pan por la mezcla, sin dejar que se deshaga.', null),
  ('rec-pan-frances-step-3', 'rec-pan-frances', 3, 'Dorar', 'Dora el pan en mantequilla a fuego medio, 2 minutos por lado.', 240),
  ('rec-pan-frances-step-4', 'rec-pan-frances', 4, 'Servir', 'Espolvorea el azúcar restante y sirve caliente.', null),
  ('rec-yogur-con-manzana-y-avena-step-1', 'rec-yogur-con-manzana-y-avena', 1, 'Picar', 'Lava la manzana y pícala en cubos.', null),
  ('rec-yogur-con-manzana-y-avena-step-2', 'rec-yogur-con-manzana-y-avena', 2, 'Servir', 'Sirve el yogur con la manzana y la avena encima.', null),
  ('rec-omelette-de-verduras-step-1', 'rec-omelette-de-verduras', 1, 'Picar', 'Pica la calabacita, el jitomate y un cuarto de cebolla.', null),
  ('rec-omelette-de-verduras-step-2', 'rec-omelette-de-verduras', 2, 'Sofreír', 'Sofríe las verduras en aceite con sal por 4 minutos.', 240),
  ('rec-omelette-de-verduras-step-3', 'rec-omelette-de-verduras', 3, 'Cuajar', 'Agrega los huevos batidos, tapa y cocina a fuego bajo 5 minutos.', 300),
  ('rec-omelette-de-verduras-step-4', 'rec-omelette-de-verduras', 4, 'Servir', 'Dobla el omelette a la mitad y sirve.', null),
  ('rec-licuado-de-platano-con-avena-step-1', 'rec-licuado-de-platano-con-avena', 1, 'Licuar', 'Licúa la leche con el plátano, la avena y el azúcar hasta que quede sin grumos.', null),
  ('rec-licuado-de-platano-con-avena-step-2', 'rec-licuado-de-platano-con-avena', 2, 'Servir', 'Sirve frío al momento.', null),
  ('rec-tinga-de-pollo-step-1', 'rec-tinga-de-pollo', 1, 'Cocer el pollo', 'Cuece la pechuga en agua con sal y ajo por 25 minutos, deshébrala.', 1500),
