  ('rec-rajas-con-crema-step-1', 'rec-rajas-con-crema', 1, 'Asar los chiles', 'Asa los chiles en el comal hasta que la piel se queme, unos 10 minutos.', 600),
  ('rec-rajas-con-crema-step-2', 'rec-rajas-con-crema', 2, 'Pelar', 'Mételos en una bolsa 5 minutos, pélalos, quita semillas y córtalos en rajas.', 300),
  ('rec-rajas-con-crema-step-3', 'rec-rajas-con-crema', 3, 'Guisar', 'Sofríe la cebolla, agrega las rajas, la crema y el queso. Cocina 5 minutos.', 300),
